const plan = [["Read the brief", 10], ["Input", 20], ["Core processing", 30], ["Testing", 20], ["Error review", 10]];
const actual = [12, 22, 41];

let cum = 0;
let planCum = 0;
actual.forEach((used, i) => {
  const [name, minutes] = plan[i];
  cum += used;
  planCum += minutes;
  const late = used - minutes;
  const status = late > 0 ? `late ${late}` : "on time";
  console.log(`${name}: ${used}/${minutes} min, total ${cum}/${planCum} - ${status}`);
});

const need = plan.slice(actual.length).reduce((s, p) => s + p[1], 0);
console.log(`${90 - cum} min left, last two parts need ${need} min: short by ${need}`);

